// Audit C3 (docs/reviews/2026-11-16-routing-coordination, README "C3" and CYCLE_CONTRACT.md steps 1, 3,
// 7 and 8): a cycle closed `verified` with no practice assessment, and no dispatch consumed a decision.
//
//   - a cycle opened under the new contract (pantheon.cycle/v2) cannot close without a recorded practice
//     assessment/disposition, even an explicit `insufficient_evidence`;
//   - a cycle opened under the old contract keeps its meaning: a ledger written before this change
//     (fixtures/cycle-v1-ledger, generated by the code at e481e77) verifies unchanged, hash for hash;
//   - a promote is refused when the deciding seat is of the candidate proposer's lab (no self-promotion);
//   - the next dispatch records the admitted disposition it loaded, from the ledger: a document edited
//     without a ledger entry changes nothing it loads.
// Every reviewer and provider is scripted; no network, no provider spend.
import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {openPantheonLedger, pantheonSystemKinds, CONTROLLER} from '../src/ledger/system.mjs';
import {openLedger} from '../../packages/ledger/index.mjs';
import {reviewCycle} from '../src/ledger/review-cycle.mjs';
import {ledgerView, CLOSE} from '../src/ledger/cycle-kinds.mjs';
import {PRACTICE, PRACTICE_SCHEMA, CYCLE_CONTRACT, CYCLE_CONTRACT_V1, DEFAULT_PRACTICE_SCOPE, admittedPractice, loadPractice}
  from '../src/ledger/practice-kinds.mjs';
import {selectionPolicy, SELECTION_POLICY} from '../src/route/frontier.mjs';
import {runOpenItem} from '../src/board/run-item.mjs';
import {withDispatch} from './fixtures/dispatch.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const C = n => String(n).repeat(40).slice(0, 40);
const DIFF = 'diff --git a/src/x.mjs b/src/x.mjs\n--- a/src/x.mjs\n+++ b/src/x.mjs\n@@ -1 +1 @@\n-export const x = 1;\n+export const x = 2;\n';
const APPROVE = '```json\n{"verdict":"approve","findings":[]}\n```';
const approve = async ({vendor, model}) => ({text: APPROVE, response_id: `resp_${vendor}_${Math.random()}`, served_model: model});
const change = (over = {}) => ({scope: 'ophanim', base: C('a'), head: C('b'), diff: DIFF, files: ['src/x.mjs'], author_labs: ['anthropic'], ...over});
const CURRENT = (() => { const id = selectionPolicy('argo', {pools: []}); return {version: id.policy, hash: id.hash, profile: 'argo'}; })();
const CANDIDATE = {id: 'review-on-cheaper-band', policy: {version: 'pantheon.selection/v1-candidate', hash: 'sha256:' + 'c'.repeat(64), profile: 'argo'},
  change: 'seat the easy-band reviewer one tier lower'};
const QUESTION = 'Does seating reviewers by difficulty band change accepted-result quality or cost?';

async function withLedger(fn) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'pantheon-practice-'));
  try {
    const sys = openPantheonLedger({root: path.join(dir, 'ledger')});
    return await fn(sys, sys.recorder(), dir);
  } finally { fs.rmSync(dir, {recursive: true, force: true}); }
}
/** A reviewed cycle with every review in, ready to close but for its practice disposition. */
const reviewed = async (rec, over = {}, opts = {}) => {
  const r = await reviewCycle({ledger: rec, change: change(over), turn: approve, ...opts});
  assert.equal(r.complete, true, JSON.stringify(r.failed));
  return r.cycle;
};
const assess = (rec, cycle, over = {}) => rec.recordDisposition({cycle, outcome: 'insufficient_evidence', question: QUESTION,
  provenance: {by: {role: 'lead@orch'}, method: 'no comparable telemetry for the question on this ledger'}, ...over});

test('C3: a cycle under the new contract cannot close without a practice disposition; an explicit insufficient_evidence lets it close', () => withLedger(async (sys, rec) => {
  const cycle = await reviewed(rec);
  const p = ledgerView(sys.ledger).payload(cycle);
  assert.equal(p.contract, CYCLE_CONTRACT, 'a new cycle records the contract it opened under');
  assert.deepEqual(p.policy, CURRENT, 'and the selection policy (version and hash) in effect');
  assert.equal(p.practice_scope, DEFAULT_PRACTICE_SCOPE);
  assert.equal(p.prior, null, 'no admitted practice decision yet: the named provisional default applies');
  // The review and finding gates are satisfied; the practice gate is not.
  assert.throws(() => rec.closeCycle(cycle), /no practice assessment/);
  // A forged close without the practice gate is refused by the ledger itself, not only by the recorder.
  const forged = {outcome: 'verified', reviews: rec.cycleState(cycle).reviews.map(r => r.hash).sort(), labs: ['google', 'openai', 'xai'],
    findings: {total: 0, fixed: 0, deferred: 0, unreproduced: 0}};
  assert.throws(() => sys.ledger.append({kind: CLOSE, payload: forged, derivedFrom: [cycle], author: {key_id: CONTROLLER}, signer: sys.controller, order: sys.controller}),
    /no practice assessment/);
  const d = assess(rec, cycle);
  const dp = ledgerView(sys.ledger).payload(d);
  assert.equal(dp.schema, PRACTICE_SCHEMA);
  assert.deepEqual(dp.policy, CURRENT, 'the disposition names the policy version and hash in effect');
  assert.equal(dp.provisional, true, 'unmeasured judgment is labelled provisional');
  const closed = rec.closeCycle(cycle);
  assert.equal(closed.outcome, 'verified');
  assert.deepEqual(closed.practice, [d], 'the close carries the cycle\'s practice dispositions');
  assert.equal(sys.ledger.verify().ok, true);
  // Nothing more for a closed cycle.
  assert.throws(() => assess(rec, cycle), /the cycle is closed/);
}));

test('C3: every assessment outcome is a bounded choice; unmeasured judgment must say it is provisional', () => withLedger(async (sys, rec) => {
  const cycle = await reviewed(rec);
  assert.throws(() => assess(rec, cycle, {outcome: 'promote'}), /assessment outcome/);
  assert.throws(() => assess(rec, cycle, {outcome: 'maybe'}), /assessment outcome/);
  assert.throws(() => assess(rec, cycle, {provisional: false}), /provisional/);
  assert.throws(() => assess(rec, cycle, {outcome: 'propose_policy'}), /candidate/, 'a policy proposal names its candidate and proposer');
  for (const outcome of ['retain', 'propose_measurement']) assess(rec, cycle, {outcome});
  assess(rec, cycle, {outcome: 'propose_policy', candidate: CANDIDATE, proposer: {vendor: 'openai', model: 'gpt-6-sol', lab: 'openai'}});
  assert.equal(rec.closeCycle(cycle).practice.length, 3);
  assert.equal(sys.ledger.verify().ok, true);
}));

test('C3: an old-contract cycle still closes and verifies unchanged: a ledger written before this change re-derives hash for hash', () => {
  const root = path.join(HERE, 'fixtures', 'cycle-v1-ledger');
  const expected = JSON.parse(fs.readFileSync(path.join(root, 'EXPECTED.json'), 'utf8'));
  const ledger = openLedger({dir: root, kinds: pantheonSystemKinds(), anchor: expected.anchor});
  const v = ledger.verify();
  assert.equal(v.ok, true, v.why);
  assert.equal(v.head, expected.head, 'the historical head is unchanged');
  assert.equal(v.entries, expected.entries);
  const view = ledgerView(ledger);
  for (const [i, h] of expected.cycles.entries()) {
    assert.equal(view.payload(h).contract, undefined, 'an old cycle carries no contract field and is read as the old contract');
    assert.deepEqual(view.payload(expected.closes[i]), expected.claims[i], 'its close means what it meant: no practice gate added');
  }
  assert.equal(admittedPractice(view, {scope: DEFAULT_PRACTICE_SCOPE, profile: 'argo'}), null, 'an old ledger admits no practice decision');
});

test('C3: the old contract can still be named explicitly, and is byte-identical; a scope never downgrades from the new one', () => withLedger(async (sys, rec) => {
  const old = await reviewed(rec, {}, {contract: CYCLE_CONTRACT_V1});
  const p = ledgerView(sys.ledger).payload(old);
  assert.deepEqual(Object.keys(p).sort(), ['author_labs', 'base', 'brief_sha', 'diff_sha', 'files', 'head', 'opened_at', 'prompt_sha', 'reviewers', 'scope']);
  const closed = rec.closeCycle(old);
  assert.deepEqual(Object.keys(closed).sort(), ['findings', 'hash', 'labs', 'outcome', 'reviews'], 'an old-contract close has no practice field');
  // The next cycle opens under the new contract; after it, the scope may not return to the old one.
  const next = await reviewed(rec, {base: undefined, head: C('d')});
  assess(rec, next);
  rec.closeCycle(next);
  await assert.rejects(reviewed(rec, {base: undefined, head: C('e')}, {contract: CYCLE_CONTRACT_V1}), /may not return to the old contract/);
  assert.equal(sys.ledger.verify().ok, true);
}));

test('C3: a self-promotion by the proposer\'s lab is refused; a seat of another lab may promote, with conditions and measured evidence', () => withLedger(async (sys, rec) => {
  const first = await reviewed(rec);
  const proposal = assess(rec, first, {outcome: 'propose_policy', candidate: CANDIDATE, proposer: {vendor: 'openai', model: 'gpt-6-sol', lab: 'openai'}});
  rec.closeCycle(first);
  const second = await reviewed(rec, {base: undefined, head: C('d')});
  // The comparison's retained evidence, as a ledger entry the promote cites (a synthetic stand-in here).
  const evidence = rec.recordTurn({seat: {seat_id: 'xai-compare@grok-4.7', vendor: 'xai', mode: 'compare', occupancy_gen: 1},
    requested_model: 'grok-4.7', served_model: 'grok-4.7', response_id: 'resp_compare', reply: 'matched baseline and candidate, synthetic'});
  const conditions = {applicability: 'argo profile, reviewer chair, easy band only', rollback: 'retain pantheon.selection/v1 on any accepted-result regression',
    reevaluate: 'after 20 comparable tickets or any change to the reviewer table'};
  const decide = over => rec.recordDisposition({cycle: second, stage: 'candidate', proposal, outcome: 'promote', question: QUESTION, measured: true,
    evidence: [{kind: 'ledger', hash: evidence}], conditions, by: {vendor: 'xai', model: 'grok-4.7', lab: 'xai'},
    provenance: {by: {role: 'check@review'}, method: 'matched synthetic comparison'}, ...over});
  assert.throws(() => decide({by: {vendor: 'openai', model: 'gpt-6-astra', lab: 'openai'}}), /proposer's lab|own promotion/);
  // A transport is not a lab: an agy seat serving a Claude lane model is the Anthropic lab.
  const anthropicProposal = assess(rec, second, {outcome: 'propose_policy', candidate: {...CANDIDATE, id: 'lane-candidate'},
    proposer: {vendor: 'anthropic', model: 'claude-opus-5-5', lab: 'anthropic'}});
  assert.throws(() => decide({proposal: anthropicProposal, by: {vendor: 'agy_google', model: 'claude-sonnet-4-6', lab: 'anthropic'}}), /proposer's lab|own promotion/);
  assert.throws(() => decide({by: {vendor: 'agy_google', model: 'claude-sonnet-4-6', lab: 'google'}}), /lab is anthropic/, 'the deciding seat\'s lab is re-derived');
  assert.throws(() => decide({conditions: {applicability: 'all', rollback: ''}}), /rollback/);
  assert.throws(() => decide({measured: false}), /measured/);
  assert.throws(() => decide({candidate: {...CANDIDATE, policy: {...CANDIDATE.policy, hash: 'sha256:' + 'd'.repeat(64)}}}), /not the one the proposal names/);
  const promoted = decide();
  assess(rec, second);
  rec.closeCycle(second);
  assert.equal(sys.ledger.verify().ok, true);
  const admitted = admittedPractice(ledgerView(sys.ledger), {scope: DEFAULT_PRACTICE_SCOPE, profile: 'argo'});
  assert.equal(admitted.disposition, promoted);
  assert.deepEqual(admitted.policy, CANDIDATE.policy, 'a promote admits the candidate policy');
}));

test('C3: the admitted practice is the latest promote/retain of a CLOSED cycle; the next cycle cites what it loaded', () => withLedger(async (sys, rec) => {
  const view = () => ledgerView(sys.ledger);
  const first = await reviewed(rec);
  const retained = assess(rec, first, {outcome: 'retain'});
  assert.equal(admittedPractice(view(), {scope: DEFAULT_PRACTICE_SCOPE, profile: 'argo'}), null, 'an open cycle\'s disposition is not admitted');
  rec.closeCycle(first);
  assert.equal(admittedPractice(view(), {scope: DEFAULT_PRACTICE_SCOPE, profile: 'argo'}).disposition, retained);
  assert.equal(admittedPractice(view(), {scope: DEFAULT_PRACTICE_SCOPE, profile: 'legacy'}), null, 'per profile');
  const second = await reviewed(rec, {base: undefined, head: C('d')});
  const sp = view().payload(second);
  assert.equal(sp.prior, retained, 'the next cycle opens with the admitted decision it loaded');
  assert.ok(view().entry(second).derived_from.includes(retained), 'and cites it');
  assess(rec, second);                                   // insufficient_evidence does not replace a retain
  rec.closeCycle(second);
  assert.equal(admittedPractice(view(), {scope: DEFAULT_PRACTICE_SCOPE, profile: 'argo'}).disposition, retained);
  // A cycle that names another prior than the ledger admits is refused.
  const forged = {...view().payload(second), base: C('d'), head: C('e'), prior: null};
  const close2 = rec.lastCycle('ophanim').close;
  assert.throws(() => sys.ledger.append({kind: 'cycle', payload: forged, derivedFrom: [close2], author: {key_id: CONTROLLER}, signer: sys.controller, order: sys.controller}),
    /prior/);
  assert.equal(sys.ledger.verify().ok, true);
}));

test('C3: the next actual dispatch records the admitted disposition it loaded; a document edited without a ledger entry does not change it', async () => {
  await withDispatch(async ({dir, spec, opts}) => {
    const root = path.join(dir, 'shared-ledger');
    process.env.OPHANIM_LEDGER = root;
    const practiceOf = r => JSON.parse(fs.readFileSync(path.join(r.board, 'run.json'), 'utf8')).turns.map(t => t.selection?.practice);

    // No decision on the ledger: the named provisional default, said so.
    const none = await runOpenItem(spec('practice-none'), opts());
    assert.equal(none.shipped, true, JSON.stringify(none.error));
    for (const p of practiceOf(none)) {
      assert.equal(p.disposition, null);
      assert.equal(p.provisional, true);
      assert.equal(p.policy.version, SELECTION_POLICY);
      assert.match(p.reason, /provisional default/);
    }

    // A cycle retains the current policy and closes: the next dispatch loads THAT entry.
    let sys = openPantheonLedger({root}), rec = sys.recorder();
    const c1 = await reviewed(rec, {scope: 'pantheon'});
    const d1 = assess(rec, c1, {outcome: 'retain'});
    rec.closeCycle(c1);
    const loaded = await runOpenItem(spec('practice-retained'), opts());
    assert.equal(loaded.shipped, true, JSON.stringify(loaded.error));
    for (const p of practiceOf(loaded)) {
      assert.equal(p.disposition, d1, 'every turn names the disposition its dispatch loaded');
      assert.equal(p.outcome, 'retain');
      assert.equal(p.applies, true, 'the retained policy is the one this dispatcher runs');
    }
    // On the ledger turn entries too.
    sys = openPantheonLedger({root});
    const turns = sys.ledger.read().filter(e => e.kind === 'turn').map(e => sys.ledger.payloadOf(e)).filter(t => t.selection);
    assert.ok(turns.some(t => t.selection.practice?.disposition === d1));

    // A document claiming a new policy, with no ledger entry: nothing it loads changes.
    fs.mkdirSync(path.join(dir, 'docs'), {recursive: true});
    fs.writeFileSync(path.join(dir, 'docs', 'routing-policy.md'), '# Routing policy\n\nPROMOTED: review-on-cheaper-band (pantheon.selection/v1-candidate).\n');
    const afterDoc = await runOpenItem(spec('practice-doc'), opts());
    assert.deepEqual([...new Set(practiceOf(afterDoc).map(p => p.disposition))], [d1], 'a document alone is not a decision');

    // A new admitted decision on the ledger is what changes it.
    rec = openPantheonLedger({root}).recorder();
    const c2 = await reviewed(rec, {scope: 'pantheon', base: undefined, head: C('d')});
    const d2 = assess(rec, c2, {outcome: 'retain', question: 'Retain after one more cycle without comparable evidence?'});
    rec.closeCycle(c2);
    const next = await runOpenItem(spec('practice-next'), opts());
    assert.deepEqual([...new Set(practiceOf(next).map(p => p.disposition))], [d2]);
    assert.equal(loadPractice({ledger: openPantheonLedger({root}).ledger, profile: 'argo', pools: []}).disposition, d2);
  });
});
